"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["93636"],{74359(e){e.exports=JSON.parse('{"id":"FUT-0030","slug":"diversification","term":"Diversification","also_known_as":[],"difficulty":"Beginner","definition":"Diversification is spreading investments across many different assets so that a loss in any one of them has a smaller effect on the whole portfolio.","explanation":["The idea is captured in the saying \\"don\'t put all your eggs in one basket\\". If all your money is in a single company and that company fails, you could lose everything. If your money is spread across hundreds of companies, the failure of one has only a small effect.","Diversification works best when investments do not all move in the same direction at the same time. Shares in different industries, countries and company sizes respond differently to events. Bonds often behave differently from shares. Combining them smooths out the overall ups and downs.","For example, suppose half your portfolio is in airline shares and half in a company that runs video calls. A sudden drop in travel might hurt the airline but help the video company. Together, the portfolio is steadier than either holding alone.","Diversification reduces the risk linked to individual companies, but it cannot remove risk entirely. When the whole market falls, as in a severe recession, most investments fall together. This market-wide risk is called systematic risk. Low-cost index funds are a simple way for individual investors to diversify widely."],"note":"","total":1725,"prev":{"slug":"distribution-waterfall","term":"Distribution Waterfall"},"next":{"slug":"divestiture","term":"Divestiture"}}')}}]);